/**
 * HudRealVictoryReward — the signed end-of-run report (R-348 ruling
 * 2026-11-16, «approvato, battezza»): `/assets/ui/hud-real/victory/frame.webp`
 * is the baptized pergamena regenerated by Gemini web from the AI family
 * «B — Pergamena suggellata» — clean writing surface, empty medallion ring,
 * painted divider, painted CTA plaque. Every DOM zone sits on a painted
 * affordance (fork card `.mw/runs/20261116-r348-victory-ruling/`).
 *
 * Behaviour contract — identical to `QuestRewardPopup` (its stock counterpart,
 * still mounted on the legacy `/game-frame-pixi` route):
 * - NON-MODAL floating report over the map (radial veil like
 *   `HudRealExpeditionLost` — the theatre keeps breathing behind it).
 * - Staged reveal: ribbon → crew → rewards → echoes → CTA; auto-advances on
 *   `stageMs`, click/any key hurries, `Escape` closes and restores focus.
 * - `run` must be ENDED — the first painted frame persists `settling`
 *   (`markRewardShown`); every close path convoglia su `onClose`, the commit
 *   boundary — the component never applies settlement effects itself (R-260).
 * - Never outgrows the viewport: the frame box is width-capped at 121vh so the
 *   whole art always fits (R-239 by construction).
 */
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import * as Tooltip from '@radix-ui/react-tooltip';
import { EngravedIcon, type EngravedIconId } from '@/ui/idleVillage/components/gameFrame/engravedIcons';
import type { QuestRunState, RuntimeMember } from '@/ui/idleVillage/questS1Lab/questRun';
import type { QuestScenario } from '@/balancing/config/idleVillage/quests/questScenario.schema';
import { buildQuestEpilogue } from '@/ui/idleVillage/quests/questEpilogue';
import { deriveSettlementPlan } from '@/ui/idleVillage/quests/questSettlement';
import { markRewardShown } from '@/ui/idleVillage/questS1Lab/questRunStore';
import { runIdOf } from '@/ui/idleVillage/quests/questSettlement';
import { DEFAULT_GAME_FRAME_CONFIG } from '@/balancing/config/idleVillage/gameFrameConfig';
import { C1Medallion } from '@/ui/idleVillage/components/C1Medallion';
import { SandboxTimingProvider, useSandboxTiming } from '@/ui/idleVillage/hooks/useSandboxTimingBridge';

const FRAME_SRC = '/assets/ui/hud-real/victory/frame.webp';
const ART_W = 1024;
const ART_H = 745;

const C = {
  ink: '#2e2118',
  inkSoft: '#4a3a28',
  label: '#33241a',
  goldHi: '#f0d68a',
  wound: '#8a4a2a',
  fallen: '#5a4a3a',
  rare: '#6a4a8a',
} as const;

interface Zone { x: number; y: number; w: number; h: number }
/** Zones in art px on the 1024×745 baptized frame — measured on the approved
 *  mockup (v5): every rect covers a painted affordance, nothing floats. */
const Z = {
  title: { x: 330, y: 14, w: 364, h: 58 },
  ribbon: { x: 250, y: 96, w: 524, h: 58 },
  chip: { x: 382, y: 300, w: 260, h: 26 },
  medal: { x: 148, y: 322, w: 156, h: 164 },
  crewLabel: { x: 326, y: 340, w: 240, h: 22 },
  crewRows: { x: 318, y: 362, w: 252, h: 140 },
  rewardsLabel: { x: 578, y: 340, w: 240, h: 22 },
  rewardsRows: { x: 574, y: 362, w: 250, h: 140 },
  echoes: { x: 288, y: 510, w: 448, h: 92 },
  cta: { x: 320, y: 614, w: 400, h: 78 },
  close: { x: 950, y: 16, w: 52, h: 52 },
} satisfies Record<string, Zone>;

const pct = (z: Zone): React.CSSProperties => ({
  position: 'absolute',
  left: `${(z.x / ART_W) * 100}%`,
  top: `${(z.y / ART_H) * 100}%`,
  width: `${(z.w / ART_W) * 100}%`,
  height: `${(z.h / ART_H) * 100}%`,
});

type CrewState = 'returned' | 'wounded' | 'fallen';
const stateOf = (m: RuntimeMember): CrewState => (m.dead ? 'fallen' : m.wounded ? 'wounded' : 'returned');

/** Run-log lines that name this person and record harm — «what happened», localized. */
const causesOf = (run: QuestRunState, m: RuntimeMember): string[] =>
  (run.log ?? [])
    .filter((e) => (e.kind === 'WOUND' || e.kind === 'DEATH') && e.text.includes(m.name))
    .map((e) => e.text);

const ROW_ICON: Record<string, EngravedIconId> = {
  reward: 'ico-cup',
  loot: 'ico-pouch',
  xp: 'ico-spark',
  consumed: 'ico-chest',
};

export interface HudRealVictoryRewardProps {
  /** An ended run — the report is read from its committed state. */
  run: QuestRunState;
  /** The authored scenario — feeds intel labels and the epilogue seams. */
  scenario?: QuestScenario;
  /** Wall-clock between reveal stages (`questWindow.rewardPopup.stageMs`). */
  stageMs?: number;
  onClose: () => void;
}

const HudRealVictoryRewardInner: React.FC<HudRealVictoryRewardProps> = ({ run, scenario, stageMs = 900, onClose }) => {
  const { t } = useTranslation('idleVillage');
  const { scheduleTimeout } = useSandboxTiming();
  const shellRef = useRef<HTMLDivElement | null>(null);
  const restoreFocusTo = useRef<HTMLElement | null>(null);

  /* art-px → css-px scale for px-prop components (C1Medallion): the container
   * is containerType-sized, so zones use % while the medallion needs real px. */
  const [artScale, setArtScale] = useState(1);
  useEffect(() => {
    const el = shellRef.current;
    if (!el) return;
    const ro = new ResizeObserver(() => setArtScale(el.clientWidth / ART_W));
    ro.observe(el);
    setArtScale(el.clientWidth / ART_W);
    return () => ro.disconnect();
  }, []);

  /* Staged reveal — same skip contract as the stock plaque: stage 0 is the
   * ribbon only, each stage paints one zone, the last unlatches the CTA. */
  const LAST_STAGE = 4;
  const [stage, setStage] = useState(0);
  const done = stage >= LAST_STAGE;
  const advance = useCallback(() => setStage((s) => Math.min(s + 1, LAST_STAGE)), []);
  useEffect(() => {
    if (done) return;
    return scheduleTimeout(advance, stageMs);
  }, [stage, done, stageMs, advance, scheduleTimeout]);

  /* Focus contract + first-painted-frame settle ack — same as stock. */
  useEffect(() => {
    restoreFocusTo.current = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    shellRef.current?.focus({ preventScroll: true });
    return () => restoreFocusTo.current?.focus?.({ preventScroll: true });
  }, []);
  useEffect(() => {
    const id = requestAnimationFrame(() => markRewardShown(run.questId, runIdOf(run)));
    return () => cancelAnimationFrame(id);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const onKeyDown = (event: React.KeyboardEvent) => {
    if (event.key === 'Escape') {
      event.stopPropagation();
      onClose();
      return;
    }
    if (event.metaKey || event.ctrlKey || event.altKey) return;
    if ((event.target as HTMLElement | null)?.closest('button, a, input, select, textarea')) return;
    event.preventDefault();
    if (!done) advance();
  };

  /* Real settlement data — the same builders the stock report reads. */
  const sections = useMemo(() => buildQuestEpilogue(run, scenario), [run, scenario]);
  const rewardRows = useMemo(
    () => sections.filter((s) => s.id === 'consumed' || s.id === 'reward' || s.id === 'loot' || s.id === 'xp'),
    [sections],
  );
  const echoRows = useMemo(
    () => sections.filter((s) => s.id === 'lore' || s.id === 'info' || s.id === 'titles' || s.id === 'diseases'),
    [sections],
  );
  const xpByMember = useMemo(() => {
    const plan = run.settlement?.plan ?? deriveSettlementPlan(run);
    const map = new Map<string, number>();
    for (const e of plan.effects) {
      if (e.kind === 'resident-xp' && e.residentId) map.set(e.residentId, (map.get(e.residentId) ?? 0) + (e.amount ?? 0));
    }
    return map;
  }, [run]);
  const grantsOf = useCallback(
    (id: 'titles' | 'diseases', memberId: string) =>
      (sections.find((s) => s.id === id)?.lines ?? []).filter((l) => l.memberId === memberId).map((l) => l.text ?? ''),
    [sections],
  );

  const fallen = run.party.filter((m) => m.dead).length;
  const anchor = run.party.find((m) => m.role === 'leader' && !m.dead) ?? run.party.find((m) => !m.dead) ?? run.party[0];
  const isWipe = run.outcome === 'wipe' || run.outcome === 'fled';
  const medalSize = Z.medal.w * artScale;
  const rowMedalSize = 22 * artScale;

  return (
    <div
      data-testid="hudreal-victory-reward"
      style={{
        position: 'fixed', inset: 0, zIndex: DEFAULT_GAME_FRAME_CONFIG.zLayers.reward,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        background: 'radial-gradient(ellipse at 50% 45%, rgba(6,18,20,.45), rgba(2,7,9,.75))',
      }}
    >
      <div
        ref={shellRef}
        role="dialog"
        aria-label={t('gameFrame.questEpilogue.title')}
        tabIndex={-1}
        onKeyDown={onKeyDown}
        onClick={done ? undefined : advance}
        style={{
          position: 'relative', outline: 'none', containerType: 'size',
          width: 'min(1040px, 92vw, 121vh)', aspectRatio: `${ART_W} / ${ART_H}`,
          filter: 'drop-shadow(0 20px 60px rgba(0,0,0,.78))',
          cursor: done ? 'default' : 'pointer',
        }}
      >
        <img src={FRAME_SRC} alt="" draggable={false} style={{ position: 'absolute', inset: 0, width: '100%', height: '100%', display: 'block' }} />

        {/* Title on the painted top plaque */}
        <div style={{ ...pct(Z.title), display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <span style={{
            fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '2.6cqh', fontWeight: 800,
            letterSpacing: '0.2em', textTransform: 'uppercase', color: '#16241f',
            textShadow: '0 1px 0 rgba(255,235,180,.4)',
          }}>
            {t('gameFrame.questEpilogue.title')}
          </span>
        </div>

        {/* Outcome on the painted teal ribbon — stage 0 */}
        <div style={{ ...pct(Z.ribbon), display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <span style={{
            fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '2.9cqh', fontWeight: 800,
            letterSpacing: '0.16em', textTransform: 'uppercase', color: '#e8dcc0',
            textShadow: '0 1px 3px rgba(0,0,0,.7)',
          }}>
            {t(`questS1Lab.outcome.${run.outcome}`)}
          </span>
        </div>

        {/* Return chip on the scene's bottom trim */}
        <div style={{ ...pct(Z.chip), display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
          <span style={{
            fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '1.55cqh', fontWeight: 700,
            letterSpacing: '0.14em', textTransform: 'uppercase', color: '#f0e6cc',
            textShadow: '0 1px 2px rgba(0,0,0,.8)', padding: '0.3cqh 1.4cqw',
            background: 'rgba(20,32,28,.72)', borderRadius: '2cqh', border: '1px solid rgba(240,214,138,.45)',
          }}>
            {run.party.length === 0 || fallen === run.party.length
              ? t('gameFrame.questWindow.noneReturned')
              : `${t('gameFrame.questWindow.returned')}${fallen > 0 ? ` · ${fallen} ${t('gameFrame.questEpilogue.crewFallen').toLowerCase()}` : ''}`}
          </span>
        </div>

        {/* Baptized medallion on the painted ring — stage 1 anchor */}
        {stage >= 1 && anchor && (
          <div style={{ ...pct(Z.medal), display: 'grid', placeItems: 'center' }}>
            <C1Medallion portraitUrl={anchor.portrait} sizePx={medalSize} />
          </div>
        )}

        {stage >= 1 && (
          <>
            <span style={{ ...pct(Z.crewLabel), fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '1.7cqh', fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: C.label, display: 'flex', alignItems: 'center' }}>
              {t('gameFrame.questEpilogue.crewTitle')}
            </span>
            <div data-testid="hudreal-victory-crew" style={{ ...pct(Z.crewRows), display: 'flex', flexDirection: 'column', justifyContent: 'space-evenly', overflowY: 'auto' }}>
              <Tooltip.Provider delayDuration={200} skipDelayDuration={150}>
                {run.party.map((m) => {
                  const state = stateOf(m);
                  const xp = xpByMember.get(m.id);
                  const causes = causesOf(run, m);
                  const titles = grantsOf('titles', m.id);
                  const diseases = grantsOf('diseases', m.id);
                  return (
                    <Tooltip.Root key={m.id}>
                      <Tooltip.Trigger asChild>
                        <button
                          type="button"
                          data-testid={`hudreal-crew-${m.id}`}
                          data-crew-state={state}
                          aria-label={`${m.name} — ${t(`gameFrame.questEpilogue.crew${state === 'returned' ? 'Returned' : state === 'wounded' ? 'Wounded' : 'Fallen'}`)}`}
                          style={{
                            all: 'unset', boxSizing: 'border-box', display: 'flex', alignItems: 'center',
                            gap: '1cqw', cursor: 'help', minWidth: 0,
                          }}
                        >
                          <span style={{ width: `${rowMedalSize}px`, height: `${rowMedalSize}px`, flexShrink: 0, filter: state === 'fallen' ? 'grayscale(1) brightness(.65)' : undefined }}>
                            <C1Medallion portraitUrl={m.portrait} sizePx={rowMedalSize} />
                          </span>
                          <span style={{
                            fontFamily: '"EB Garamond", serif', fontSize: '1.75cqh', fontWeight: 700,
                            color: state === 'fallen' ? C.fallen : C.ink, textDecoration: state === 'fallen' ? 'line-through' : undefined,
                            whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', flex: '0 1 auto', minWidth: 0,
                            textShadow: '0 1px 0 rgba(255,240,200,.35)',
                          }}>
                            {m.name}
                          </span>
                          <span style={{
                            fontFamily: 'Cinzel, serif', fontSize: '1.15cqh', fontWeight: 700, letterSpacing: '0.1em', textTransform: 'uppercase',
                            color: state === 'fallen' ? '#efe6d2' : '#f5ecd6',
                            background: state === 'fallen' ? '#4a3d30' : state === 'wounded' ? '#7a4a2c' : '#4a5e42',
                            padding: '0.2cqh 0.6cqw', borderRadius: '0.8cqh', flexShrink: 0,
                          }}>
                            {t(`gameFrame.questEpilogue.crew${state === 'returned' ? 'Returned' : state === 'wounded' ? 'Wounded' : 'Fallen'}`)}
                          </span>
                          {xp !== undefined && (
                            <span style={{ fontFamily: '"EB Garamond", serif', fontSize: '1.5cqh', fontWeight: 600, color: C.inkSoft, whiteSpace: 'nowrap' }}>
                              +{xp} XP
                            </span>
                          )}
                        </button>
                      </Tooltip.Trigger>
                      <Tooltip.Portal>
                        <Tooltip.Content
                          side="top" sideOffset={8} collisionPadding={8}
                          data-testid={`hudreal-crew-tip-${m.id}`}
                          style={{
                            zIndex: 2600, width: 262, padding: '10px 12px', borderRadius: 8, pointerEvents: 'none',
                            border: '1px solid var(--skin-hud-brass-hi)',
                            background: 'linear-gradient(180deg, var(--skin-hud-lacquer-base), var(--skin-hud-lacquer-deep))',
                            boxShadow: '0 14px 28px var(--skin-hud-lacquer-deep)',
                          }}
                        >
                          <div style={{ display: 'flex', justifyContent: 'space-between', gap: 8, font: '600 13px var(--skin-font-display)', letterSpacing: '0.08em', textTransform: 'uppercase', color: 'var(--skin-title-color)' }}>
                            {m.name}
                          </div>
                          <dl style={{ margin: '8px 0 0', display: 'grid', gridTemplateColumns: 'auto 1fr', gap: '5px 10px', font: '14px/1.3 var(--skin-font-serif)', color: 'var(--skin-text-primary)' }}>
                            {causes.length > 0 && (<><dt style={{ font: '500 12px var(--skin-font-display)', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--skin-text-secondary)' }}>{t('gameFrame.questEpilogue.tipCause')}</dt><dd style={{ margin: 0 }}>{causes.join(' ')}</dd></>)}
                            <dt style={{ font: '500 12px var(--skin-font-display)', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--skin-text-secondary)' }}>{t('gameFrame.questEpilogue.tipTitles')}</dt>
                            <dd style={{ margin: 0 }}>{titles.length > 0 ? titles.join(', ') : '—'}</dd>
                            <dt style={{ font: '500 12px var(--skin-font-display)', letterSpacing: '0.1em', textTransform: 'uppercase', color: 'var(--skin-text-secondary)' }}>{t('gameFrame.questEpilogue.tipDiseases')}</dt>
                            <dd style={{ margin: 0 }}>{diseases.length > 0 ? diseases.join(', ') : '—'}</dd>
                          </dl>
                        </Tooltip.Content>
                      </Tooltip.Portal>
                    </Tooltip.Root>
                  );
                })}
              </Tooltip.Provider>
            </div>
          </>
        )}

        {/* Rewards column on the right writing field — stage 2 */}
        {stage >= 2 && (
          <>
            <span style={{ ...pct(Z.rewardsLabel), fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '1.7cqh', fontWeight: 700, letterSpacing: '0.18em', textTransform: 'uppercase', color: C.label, display: 'flex', alignItems: 'center' }}>
              {t('questReward.rewards')}
            </span>
            <div data-testid="hudreal-victory-rewards" style={{ ...pct(Z.rewardsRows), display: 'flex', flexDirection: 'column', justifyContent: 'space-evenly', overflowY: 'auto' }}>
              {rewardRows.map((section) =>
                section.lines.map((line, i) => (
                  <span
                    key={`${section.id}-${i}`}
                    data-reward-section={section.id}
                    style={{
                      display: 'flex', alignItems: 'center', gap: '0.7cqw', minWidth: 0,
                      fontFamily: '"EB Garamond", serif', fontSize: '1.7cqh', fontWeight: 600,
                      color: section.id === 'consumed' ? C.wound : C.ink,
                      textDecoration: section.id === 'consumed' ? 'line-through' : undefined,
                      textShadow: '0 1px 0 rgba(255,240,200,.3)',
                    }}
                  >
                    <EngravedIcon id={ROW_ICON[section.id] ?? 'ico-pouch'} size={11} aria-hidden style={{ flexShrink: 0, color: C.inkSoft }} />
                    <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                      {line.key ? t(line.key, line.params) : line.text}
                    </span>
                  </span>
                )),
              )}
            </div>
          </>
        )}

        {/* Echoes under the painted divider — stage 3 */}
        {stage >= 3 && (
          <div data-testid="hudreal-victory-echoes" style={{ ...pct(Z.echoes), display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: '0.4cqh', overflowY: 'auto', textAlign: 'center' }}>
            {echoRows.length > 0 ? (
              echoRows.map((section) => (
                <React.Fragment key={section.id}>
                  <span style={{ fontFamily: 'Cinzel, serif', fontSize: '1.3cqh', fontWeight: 700, letterSpacing: '0.16em', textTransform: 'uppercase', color: C.label }}>
                    {t(`gameFrame.questEpilogue.${section.id}`)}
                  </span>
                  {section.lines.map((line, i) => (
                    <span key={i} style={{ fontFamily: '"EB Garamond", serif', fontStyle: 'italic', fontSize: '1.6cqh', color: C.inkSoft }}>
                      {line.key ? t(line.key, line.params) : line.text}
                    </span>
                  ))}
                </React.Fragment>
              ))
            ) : (
              <span style={{ fontFamily: '"EB Garamond", serif', fontStyle: 'italic', fontSize: '1.6cqh', color: C.inkSoft }}>—</span>
            )}
            {!done && (
              <span style={{ fontFamily: '"EB Garamond", serif', fontStyle: 'italic', fontSize: '1.4cqh', color: C.inkSoft }}>
                {t('gameFrame.questWindow.rewardHint')}
              </span>
            )}
          </div>
        )}

        {/* CTA on the painted bottom plaque — last stage */}
        {done && (
          <button
            type="button"
            data-testid="quest-reward-collect"
            onClick={(e) => { e.stopPropagation(); onClose(); }}
            style={{
              ...pct(Z.cta), padding: 0, border: 'none', background: 'transparent', cursor: 'pointer',
              display: 'flex', alignItems: 'center', justifyContent: 'center',
              fontFamily: 'Cinzel, "EB Garamond", serif', fontSize: '2.4cqh', fontWeight: 800,
              letterSpacing: '0.22em', textTransform: 'uppercase', color: C.goldHi,
              textShadow: '0 1px 4px rgba(0,0,0,.9)',
            }}
          >
            {t(isWipe ? 'questChronicle.closeReport' : 'questChronicle.collectRewards')}
          </button>
        )}

        {/* Close X on the brass cap */}
        <button
          type="button"
          aria-label={t('gameFrame.questWindow.rewardClose')}
          title={t('gameFrame.questWindow.rewardClose')}
          onClick={(e) => { e.stopPropagation(); onClose(); }}
          style={{
            ...pct(Z.close), padding: 0, border: 'none', background: 'transparent', cursor: 'pointer',
            display: 'flex', alignItems: 'center', justifyContent: 'center',
          }}
        >
          <EngravedIcon id="cmd-close" size={Math.round(16 * artScale)} style={{ color: '#e8dcc0', filter: 'drop-shadow(0 1px 2px rgba(0,0,0,.8))' }} />
        </button>
      </div>
    </div>
  );
};

export const HudRealVictoryReward: React.FC<HudRealVictoryRewardProps> = (props) => (
  <SandboxTimingProvider>
    <HudRealVictoryRewardInner {...props} />
  </SandboxTimingProvider>
);

export default HudRealVictoryReward;
